using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    int64 gcd_ab = gcd(a, b);
    int64 common = (a > n / (b / gcd_ab))
                       ? 0
                       : n / (a * (b / gcd_ab));

    int64 count_a = n / a - common;
    int64 count_b = n / b - common;

    cout << count_a * p + count_b * q + common * max(p, q);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using LL = long long;

LL helper() {
    LL n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    LL common = 0;
    LL g = gcd(a, b);

    if (a / g <= n / b) {
        LL lcm = (a / g) * b;
        common = n / lcm;
    }

    LL cntA = n / a - common;
    LL cntB = n / b - common;

    return cntA * p + cntB * q + common * max(p, q);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << helper();
    return 0;
}

